begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('66000000-0000-4000-8000-00000000000'||i)::uuid,'authenticated','authenticated','gate-'||i||'@local.test','{}','{}',now(),now() from generate_series(1,2)i;
insert into public.profiles(id,username,nickname,synthetic_email)
select ('66000000-0000-4000-8000-00000000000'||i)::uuid,'qa_gate_v1_'||i,'Gate QA','gate-'||i||'@local.test' from generate_series(1,2)i;
insert into public.wiki_pages(page_id,canonical_title) values('gate-A','Gate A'),('gate-B','Gate B');
insert into public.wiki_page_snapshots(page_id,revision_id,canonical_title_snapshot) values('gate-A','gate-rev-A','Gate A'),('gate-B','gate-rev-B','Gate B');
create temp table cases(name text primary key,room uuid,code text);
select set_config('request.jwt.claim.sub','66000000-0000-4000-8000-000000000001',true);
insert into cases select 'start',id,room_code from public.create_discoverable_duel_room_v1(true,true);
insert into cases select 'join',id,room_code from public.create_discoverable_duel_room_v1(true,true);
insert into cases select 'active',id,room_code from public.create_duel_room_v2(true);
select set_config('request.jwt.claim.sub','66000000-0000-4000-8000-000000000002',true);
select public.join_duel_room_v2(code) from cases where name in('start','active');
update public.room_players set target_title='Gate B',target_page_id='gate-B',target_revision_id='gate-rev-B' where room_id=(select room from cases where name='start');
update public.game_rooms set status='starting',duel_start_title='Gate A',duel_start_page_id='gate-A',duel_start_revision_id='gate-rev-A' where id=(select room from cases where name='active');
update private.duel_release_control_v1 set entry_open=false;
select set_config('request.jwt.claim.sub','66000000-0000-4000-8000-000000000001',true);
select throws_ok('select public.create_duel_room_v2(true)','P0001','DUEL_ENTRY_PAUSED','legacy base create blocked');
select throws_ok('select public.create_discoverable_duel_room_v1(true,true)','P0001','DUEL_ENTRY_PAUSED','discoverable wrapper blocked');
select set_config('request.jwt.claim.sub','66000000-0000-4000-8000-000000000002',true);
select throws_ok($q$select public.join_duel_room_v2(code) from cases where name='join'$q$,'P0001','DUEL_ENTRY_PAUSED','code join blocked');
select throws_ok($q$select public.join_public_room_v1(room) from cases where name='join'$q$,'P0001','DUEL_ENTRY_PAUSED','public join wrapper blocked');
select set_config('request.jwt.claim.sub','66000000-0000-4000-8000-000000000001',true);
select throws_ok($q$select public.start_duel_room_v2(room,'Gate A','gate-A','gate-rev-A') from cases where name='start'$q$,'P0001','DUEL_ENTRY_PAUSED','waiting to starting blocked');
select lives_ok($q$select public.initialize_duel_player_v2(room,'Gate A','gate-A','gate-rev-A') from cases where name='active'$q$,'existing starting game can initialize');
select set_config('request.jwt.claim.sub','66000000-0000-4000-8000-000000000002',true);
select lives_ok($q$select public.initialize_duel_player_v2(room,'Gate A','gate-A','gate-rev-A') from cases where name='active'$q$,'second participant can initialize during drain');
select is((select status from public.game_rooms where id=(select room from cases where name='active')),'playing','starting game reaches playing during drain');
select lives_ok($q$select public.heartbeat_duel_v2(room) from cases where name='active'$q$,'heartbeat remains allowed');
select ok(not has_table_privilege('authenticated','public.game_rooms','INSERT'),'direct client room creation has no grant');
select ok(not has_table_privilege('authenticated','public.room_players','INSERT'),'direct client join has no grant');
select ok(not has_table_privilege('authenticated','private.duel_release_control_v1','UPDATE'),'member cannot open gate');
select ok(not has_function_privilege('service_role','private.assert_duel_entry_v1()','EXECUTE'),'service cannot call private gate helper');
update private.duel_release_control_v1 set entry_open=true,required_protocol='search-authority-v1';
select throws_ok('select public.create_duel_room_v2(true)','P0001','DUEL_CLIENT_RELOAD_REQUIRED','old tab rejected after reopening');
select set_config('request.headers','{"x-wiki-duel-protocol":"outdated"}',true);
select throws_ok('select public.create_duel_room_v2(true)','P0001','DUEL_CLIENT_RELOAD_REQUIRED','wrong client version rejected');
select set_config('request.headers','{"x-wiki-duel-protocol":"search-authority-v1"}',true);
select lives_ok('select public.create_discoverable_duel_room_v1(false,false)','new client can create');

create temp table permits(event uuid,grant_id uuid);
insert into permits(grant_id) select id from public.duel_item_grants where false;
insert into public.duel_item_grants(room_id,user_id,slot_index,slot_role,item_id)
select room,'66000000-0000-4000-8000-000000000002',3,'search','search_once' from cases where name='active';
insert into permits(grant_id) select id from public.duel_item_grants where room_id=(select room from cases where name='active') and item_id='search_once' and user_id='66000000-0000-4000-8000-000000000002';
update private.duel_release_control_v1 set search_enabled=false;
select is(public.use_duel_item_v3((select room from cases where name='active'),grant_id,extensions.gen_random_uuid(),extensions.gen_random_uuid())->>'code','SEARCH_DISABLED','kill switch blocks activation') from permits;
select ok((select consumed_at is null from public.duel_item_grants where id=grant_id),'disabled activation leaves slot untouched') from permits;
select is((select count(*)::int from public.duel_item_events where room_id=(select room from cases where name='active')),0,'disabled search adds no event or cooldown');
update private.duel_release_control_v1 set search_enabled=true;
update permits set event=(public.use_duel_item_v3((select room from cases where name='active'),grant_id,extensions.gen_random_uuid(),extensions.gen_random_uuid())->>'item_event_id')::uuid;
select ok(event is not null,'same slot can activate after recovery') from permits;
select public.put_duel_search_document_v1((select room from cases where name='active'),event,'66000000-0000-4000-8000-000000000002',repeat('a',64),'<p>hello</p>','["hello"]') from permits;
select public.commit_duel_search_v1((select room from cases where name='active'),event,'66000000-0000-4000-8000-000000000002','66000000-0000-4000-8000-000000000101','hello',repeat('a',64),1) from permits;
update private.duel_release_control_v1 set search_enabled=false;
select is(public.get_duel_search_source_v1((select room from cases where name='active'),event)->>'code','SEARCH_DISABLED','kill switch closes active prepare/search source') from permits;
select is(public.commit_duel_search_v1((select room from cases where name='active'),event,'66000000-0000-4000-8000-000000000002',extensions.gen_random_uuid(),'hello',repeat('a',64),1)->>'code','SEARCH_DISABLED','direct trusted commit also closes') from permits;
update private.duel_release_control_v1 set search_enabled=true;
select is(public.commit_duel_search_v1((select room from cases where name='active'),event,'66000000-0000-4000-8000-000000000002','66000000-0000-4000-8000-000000000101','hello',repeat('a',64),1)->>'code','SEARCH_FOUND','same ID replay survives switch recovery') from permits;
select is(public.commit_duel_search_v1((select room from cases where name='active'),event,'66000000-0000-4000-8000-000000000002',extensions.gen_random_uuid(),'hello',repeat('a',64),1)->>'code','SEARCH_USED','recovery cannot create a second success') from permits;

update private.duel_search_documents_v1 set created_at=clock_timestamp()-interval '31 days' where snapshot_id in(select id from public.wiki_page_snapshots where page_id='gate-A');
select private.prune_duel_search_v1(100);
select is((select count(*)::int from private.duel_search_documents_v1 where snapshot_id in(select id from public.wiki_page_snapshots where page_id='gate-A')),1,'live referenced old document survives GC');
select is((select count(*)::int from private.duel_search_requests_v1 where item_event_id in(select event from permits)),1,'live retry record survives GC');
update private.duel_search_sessions_v1 set expires_at=clock_timestamp()-interval '8 days' where item_event_id in(select event from permits);
select private.prune_duel_search_v1(100);
select is((select count(*)::int from private.duel_search_sessions_v1 where item_event_id in(select event from permits)),1,'unsettled game retains expired session');
select lives_ok($q$select public.leave_duel_room_v2(room,extensions.gen_random_uuid()) from cases where name='active'$q$,'retire and result settlement remain allowed');
select private.prune_duel_search_v1(100);
select is((select count(*)::int from private.duel_search_sessions_v1 where item_event_id in(select event from permits)),0,'finished expired session removed after retention');
select is((select count(*)::int from private.duel_search_requests_v1 where item_event_id in(select event from permits)),0,'old requests cascade with expired session');
select is((select count(*)::int from private.duel_search_documents_v1 where snapshot_id in(select id from public.wiki_page_snapshots where page_id='gate-A')),0,'old unreferenced cache removed');
select is((select count(*)::int from public.duel_item_events where room_id=(select room from cases where name='active')),1,'append-only item event survives retention');
select ok(not has_function_privilege('authenticated','private.prune_duel_search_v1(integer)','EXECUTE'),'client cannot run GC');
select ok(not has_function_privilege('service_role','private.prune_duel_search_v1(integer)','EXECUTE'),'service API cannot run GC');
select * from finish();
rollback;
